/**
 * Runtime cross-check that the hand-classified matrix hasn't drifted from
 * what the registries now say. The Record<AskOperationId, ...> type above
 * already forces every operation to have an entry (or tsc fails); this adds
 * semantic checks a type can't express.
 */
export function validateAskInteractionCoverageMatrix(): string[] {
  const issues: string[] = [];
  for (const operationId of Object.keys(ASK_OPERATION_DEFINITIONS) as AskOperationId[]) {
    const def = ASK_OPERATION_DEFINITIONS[operationId];
    const entry = ASK_INTERACTION_COVERAGE_MATRIX[operationId];
    if (!entry) { issues.push(`${operationId}: no coverage-matrix entry (Phase 0 drift)`); continue; }
    if (entry.canonicalOwner !== def.adapterKey) issues.push(`${operationId}: canonicalOwner "${entry.canonicalOwner}" no longer matches adapterKey "${def.adapterKey}"`);
    if (entry.roleFloor !== def.propertyRoleFloor) issues.push(`${operationId}: roleFloor "${entry.roleFloor}" no longer matches propertyRoleFloor "${def.propertyRoleFloor}"`);
    const isBoundary = def.safetyClass.endsWith('_BOUNDARY');
    if (isBoundary && entry.rollClass !== 'BOUNDARY_RESPONSE') issues.push(`${operationId}: safetyClass is a boundary but rollClass is "${entry.rollClass}"`);
    const hasCommand = Object.values(ASK_DOMAIN_COMMAND_REGISTRY).some((c) => c.operationId === operationId);
    if (entry.confirmationCapable !== hasCommand) issues.push(`${operationId}: confirmationCapable=${entry.confirmationCapable} no longer matches domain command registry (has entry: ${hasCommand})`);
    if (hasCommand && entry.rollClass !== 'CONFIRMED_MUTATION') issues.push(`${operationId}: has a domain command but rollClass is "${entry.rollClass}", not CONFIRMED_MUTATION`);
  }
  return issues;
}
